<!-- @FIGURE_UI_BEGIN -->
<label>Elapsed time after opening stopcock: <output id="elapsedTimeVal">0</output><input id="elapsedTimeInput" type="range" min="0" max="100" step="1" value="0" oninput="document.getElementById('elapsedTimeVal').value=this.value;update_elapsedTime(+this.value)"></label><button id="diffusionPlaybackInput" onclick="trigger_diffusionPlayback()">▶ Play diffusion</button><label><input id="massCodingInput" type="checkbox" onchange="toggle_massCoding(this.checked)"> Molecular mass emphasis</label><span id="demoNarration" style="display:block;margin:0;font-size:10px;max-width:180px;line-height:1.25"></span><span><button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button></span>
