// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1300, 344);

var glassFill = '#dceff0';
var glassStroke = '#9dc8c9';
var whiteGas = '#ffffff';
var redGas = '#d81b0c';
var blueFast = '#63c7f4';
var darkRedSlow = '#a9140b';

var currentTime = 0;
var massMode = false;
var playing = false;
var rafId = null;
var currentStep = 0;

function rng(seed) {
  var s = seed >>> 0;
  return function () {
    s = (1664525 * s + 1013904223) >>> 0;
    return s / 4294967296;
  };
}
var random = rng(42);

function bulbPoint(cx, cy, r, rand) {
  var a = rand() * Math.PI * 2;
  var rr = Math.sqrt(rand()) * (r - 17);
  return { x: cx + Math.cos(a) * rr, y: cy + Math.sin(a) * rr, side: cx < 650 ? 'left' : 'right' };
}
function tubePoint(panel, rand) {
  var x1 = panel.lx + panel.r - 8;
  var x2 = panel.rx - panel.r + 8;
  return { x: x1 + rand() * (x2 - x1), y: panel.cy - 12 + rand() * 24, side: 'tube' };
}
function finalPoint(panel, rand) {
  var q = rand();
  if (q < 0.46) return bulbPoint(panel.lx, panel.cy, panel.r, rand);
  if (q < 0.92) return bulbPoint(panel.rx, panel.cy, panel.r, rand);
  return tubePoint(panel, rand);
}
function pathPosition(points, u) {
  if (u <= 0) return points[0];
  if (u >= 1) return points[points.length - 1];
  var d = [], total = 0;
  for (var i = 0; i < points.length - 1; i++) {
    var dx = points[i + 1].x - points[i].x;
    var dy = points[i + 1].y - points[i].y;
    d[i] = Math.sqrt(dx * dx + dy * dy);
    total += d[i];
  }
  var target = u * total;
  var acc = 0;
  for (var j = 0; j < d.length; j++) {
    if (acc + d[j] >= target) {
      var f = (target - acc) / d[j];
      return {
        x: points[j].x + (points[j + 1].x - points[j].x) * f,
        y: points[j].y + (points[j + 1].y - points[j].y) * f
      };
    }
    acc += d[j];
  }
  return points[points.length - 1];
}
function ease(u) {
  u = Math.max(0, Math.min(1, u));
  return u * u * (3 - 2 * u);
}

var panels = [
  { lx: 100, rx: 330, cy: 130, r: 82, caption: 'Stopcock closed', sub: '(a)' },
  { lx: 530, rx: 760, cy: 130, r: 82, caption: 'Stopcock open', sub: '(b)' },
  { lx: 960, rx: 1190, cy: 130, r: 82, caption: 'Some time after\nStopcock open', sub: '(c)' }
];

function makeParticles(panel) {
  var h = [], o = [];
  var local = rng(1000 + panel.lx);
  for (var i = 0; i < 30; i++) {
    h.push({
      gas: 'H2',
      start: bulbPoint(panel.lx, panel.cy, panel.r, local),
      end: finalPoint(panel, local),
      jitter: local()
    });
  }
  for (var j = 0; j < 28; j++) {
    o.push({
      gas: 'O2',
      start: bulbPoint(panel.rx, panel.cy, panel.r, local),
      end: finalPoint(panel, local),
      jitter: local()
    });
  }
  return h.concat(o);
}
for (var pi = 0; pi < panels.length; pi++) panels[pi].particles = makeParticles(panels[pi]);

var statusText = draw.text('').font({ family: 'sans-serif', size: 17 }).attr({
  x: 650, y: 18, 'text-anchor': 'middle', 'dominant-baseline': 'middle',
  'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round'
}).fill('#222');

var legend = draw.group();

function centerLabel(txt, x, y, size) {
  return draw.text(txt).font({ family: 'sans-serif', size: size || 22 }).attr({
    x: x, y: y, 'text-anchor': 'middle', 'dominant-baseline': 'middle',
    'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round'
  }).fill('#000');
}

function drawApparatus(panel, idx) {
  var g = draw.group();

  g.circle(panel.r * 2).center(panel.lx, panel.cy)
    .fill({ color: glassFill, opacity: 0.78 })
    .stroke({ color: glassStroke, width: 4 });
  g.circle(panel.r * 2).center(panel.rx, panel.cy)
    .fill({ color: glassFill, opacity: 0.78 })
    .stroke({ color: glassStroke, width: 4 });

  var x1 = panel.lx + panel.r - 12;
  var x2 = panel.rx - panel.r + 12;
  g.rect(x2 - x1, 34).move(x1, panel.cy - 17)
    .fill({ color: glassFill, opacity: 0.78 })
    .stroke({ color: glassStroke, width: 4 })
    .radius(16);

  panel.trailLayer = draw.group();
  panel.particleLayer = draw.group();
  panel.motionLayer = draw.group();
  panel.valveLayer = draw.group();

  var hit = g.rect(panel.rx - panel.lx + 2 * panel.r, 180)
    .move(panel.lx - panel.r, panel.cy - panel.r - 5)
    .fill({ color: '#fff', opacity: 0 });
  hit.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip('Two connected glass bulbs: particles can mix only when the stopcock is open.', e);
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Diffusion apparatus',
        'Opening the stopcock removes the barrier between the gases. Individual particles still move randomly, but the net effect is spreading from high concentration toward low concentration.');
    });

  if (idx === 0) {
    centerLabel('H₂', panel.lx, 16, 24);
    centerLabel('O₂', panel.rx, 16, 24);
  }

  if (panel.caption.indexOf('\n') >= 0) {
    var bits = panel.caption.split('\n');
    centerLabel(bits[0], (panel.lx + panel.rx) / 2, 255, 24);
    centerLabel(bits[1], (panel.lx + panel.rx) / 2, 283, 24);
    centerLabel(panel.sub, (panel.lx + panel.rx) / 2, 321, 22);
  } else {
    centerLabel(panel.caption, (panel.lx + panel.rx) / 2, 286, 24);
    centerLabel(panel.sub, (panel.lx + panel.rx) / 2, 323, 22);
  }
}
for (var i = 0; i < panels.length; i++) drawApparatus(panels[i], i);

function drawValve(panel, open) {
  var x = (panel.lx + panel.rx) / 2;
  var y = panel.cy;
  var vg = panel.valveLayer;
  vg.clear();

  vg.rect(28, 62).center(x, y)
    .fill({ color: '#d7eeee', opacity: 0.92 })
    .stroke({ color: glassStroke, width: 4 })
    .radius(5);
  vg.circle(22).center(x, y)
    .fill({ color: '#eefafa', opacity: 0.95 })
    .stroke({ color: glassStroke, width: 3 });

  if (open) {
    vg.line(x - 18, y, x + 18, y).stroke({ color: '#ffffff', width: 8, linecap: 'round' });
    vg.line(x - 26, y - 45, x + 26, y - 45).stroke({ color: glassStroke, width: 5, linecap: 'round' });
    vg.line(x, y - 34, x - 13, y - 45).stroke({ color: glassStroke, width: 4, linecap: 'round' });
    vg.line(x, y - 34, x + 13, y - 45).stroke({ color: glassStroke, width: 4, linecap: 'round' });
  } else {
    vg.line(x, y - 19, x, y + 19).stroke({ color: glassStroke, width: 9, linecap: 'round' });
    vg.line(x - 18, y, x + 18, y).stroke({ color: '#b6d6d7', width: 4, linecap: 'round' });
    vg.line(x - 3, y - 45, x - 3, y - 22).stroke({ color: glassStroke, width: 5, linecap: 'round' });
    vg.ellipse(48, 16).center(x, y - 45)
      .fill({ color: '#e9f7f7', opacity: 0.8 })
      .stroke({ color: glassStroke, width: 4 });
  }

  vg.rect(18, 25).center(x, y + 29)
    .fill({ color: '#e9f7f7', opacity: 0.9 })
    .stroke({ color: glassStroke, width: 3 });
  vg.line(x - 13, y + 42, x + 13, y + 42).stroke({ color: glassStroke, width: 4, linecap: 'round' });

  vg.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip(open ? 'Open stopcock: gas particles can pass through the tube.' : 'Closed stopcock: the gases are separated.', e);
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup(open ? 'Stopcock open' : 'Stopcock closed',
        open ? 'Once the passage is open, particles from both bulbs enter the tube. Because H₂ is lighter, its particles spread into the opposite bulb sooner.' : 'When the valve is closed, each gas remains confined to its original bulb and no mixing can occur.');
    });
}

function particlePosition(panel, p, t) {
  var progress;
  if (p.gas === 'H2') progress = Math.min(1, Math.pow(t / 58, 0.82));
  else progress = Math.min(1, Math.pow(t / 96, 0.92));
  progress = ease(progress);

  var opposite = (p.gas === 'H2' && p.end.side === 'right') || (p.gas === 'O2' && p.end.side === 'left') || p.end.side === 'tube';
  if (!opposite) {
    var wiggle = Math.sin((t * 0.11) + p.jitter * 8) * 5 * (t / 100);
    return {
      x: p.start.x + (p.end.x - p.start.x) * progress + wiggle,
      y: p.start.y + (p.end.y - p.start.y) * progress + Math.cos((t * 0.09) + p.jitter * 9) * 4 * (t / 100)
    };
  }

  var tubeY = panel.cy - 7 + p.jitter * 14;
  var leftMouth = { x: panel.lx + panel.r - 8, y: tubeY };
  var mid = { x: (panel.lx + panel.rx) / 2, y: tubeY };
  var rightMouth = { x: panel.rx - panel.r + 8, y: tubeY };
  var route = p.gas === 'H2'
    ? [p.start, leftMouth, mid, rightMouth, p.end]
    : [p.start, rightMouth, mid, leftMouth, p.end];
