      var oldT = Math.max(0, t - (p.gas === 'H2' ? 16 : 8));
      var old = particlePosition(panel, p, oldT);
      panel.trailLayer.line(old.x, old.y, pos.x, pos.y)
        .stroke({
          color: p.gas === 'H2' ? blueFast : darkRedSlow,
          width: p.gas === 'H2' ? 2.2 : 1.5,
          opacity: p.gas === 'H2' ? 0.34 : 0.22,
          linecap: 'round'
        });
    }

    var fill = p.gas === 'H2'
      ? (massMode ? '#e8fbff' : whiteGas)
      : (massMode ? darkRedSlow : redGas);
    var stroke = p.gas === 'H2' ? '#ffffff' : redGas;
    var r = p.gas === 'H2' && massMode ? 5.2 : 5.5;

    var dot = panel.particleLayer.circle(r * 2).center(pos.x, pos.y)
      .fill(fill)
      .stroke({ color: stroke, width: p.gas === 'H2' ? 1 : 0, opacity: 0.9 });

    dot.css('cursor', 'pointer')
      .on('mousemove', (function (gas) {
        return function (e) {
          showTooltip(gas === 'H2' ? 'H₂: lighter particles diffuse faster.' : 'O₂: heavier particles diffuse more slowly.', e);
        };
      })(p.gas))
      .on('mouseleave', function () { hideTooltip(); });
  }
}

function updateLegend() {
  legend.clear();
  var x = 1105, y = 18;
  legend.rect(176, 45).move(x - 18, y - 8).fill({ color: '#fff', opacity: 0.72 }).stroke('none');
  if (massMode) {
