    .fill({ color: '#fff', opacity: 0 });
  hit.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip('Two connected glass bulbs: particles can mix only when the stopcock is open.', e);
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Diffusion apparatus',
        'Opening the stopcock removes the barrier between the gases. Individual particles still move randomly, but the net effect is spreading from high concentration toward low concentration.');
    });

  if (idx === 0) {
    centerLabel('H₂', panel.lx, 16, 24);
    centerLabel('O₂', panel.rx, 16, 24);
  }

  if (panel.caption.indexOf('\n') >= 0) {
    var bits = panel.caption.split('\n');
    centerLabel(bits[0], (panel.lx + panel.rx) / 2, 255, 24);
    centerLabel(bits[1], (panel.lx + panel.rx) / 2, 283, 24);
    centerLabel(panel.sub, (panel.lx + panel.rx) / 2, 321, 22);
  } else {
    centerLabel(panel.caption, (panel.lx + panel.rx) / 2, 286, 24);
    centerLabel(panel.sub, (panel.lx + panel.rx) / 2, 323, 22);
  }
}
for (var i = 0; i < panels.length; i++) drawApparatus(panels[i], i);

function drawValve(panel, open) {
  var x = (panel.lx + panel.rx) / 2;
  var y = panel.cy;
  var vg = panel.valveLayer;
  vg.clear();

  vg.rect(28, 62).center(x, y)
    .fill({ color: '#d7eeee', opacity: 0.92 })
    .stroke({ color: glassStroke, width: 4 })
    .radius(5);
  vg.circle(22).center(x, y)
    .fill({ color: '#eefafa', opacity: 0.95 })
    .stroke({ color: glassStroke, width: 3 });

  if (open) {
    vg.line(x - 18, y, x + 18, y).stroke({ color: '#ffffff', width: 8, linecap: 'round' });
    vg.line(x - 26, y - 45, x + 26, y - 45).stroke({ color: glassStroke, width: 5, linecap: 'round' });
    vg.line(x, y - 34, x - 13, y - 45).stroke({ color: glassStroke, width: 4, linecap: 'round' });
    vg.line(x, y - 34, x + 13, y - 45).stroke({ color: glassStroke, width: 4, linecap: 'round' });
  } else {
    vg.line(x, y - 19, x, y + 19).stroke({ color: glassStroke, width: 9, linecap: 'round' });
    vg.line(x - 18, y, x + 18, y).stroke({ color: '#b6d6d7', width: 4, linecap: 'round' });
    vg.line(x - 3, y - 45, x - 3, y - 22).stroke({ color: glassStroke, width: 5, linecap: 'round' });
    vg.ellipse(48, 16).center(x, y - 45)
      .fill({ color: '#e9f7f7', opacity: 0.8 })
      .stroke({ color: glassStroke, width: 4 });
  }

  vg.rect(18, 25).center(x, y + 29)
    .fill({ color: '#e9f7f7', opacity: 0.9 })
    .stroke({ color: glassStroke, width: 3 });
  vg.line(x - 13, y + 42, x + 13, y + 42).stroke({ color: glassStroke, width: 4, linecap: 'round' });

  vg.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip(open ? 'Open stopcock: gas particles can pass through the tube.' : 'Closed stopcock: the gases are separated.', e);
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup(open ? 'Stopcock open' : 'Stopcock closed',
        open ? 'Once the passage is open, particles from both bulbs enter the tube. Because H₂ is lighter, its particles spread into the opposite bulb sooner.' : 'When the valve is closed, each gas remains confined to its original bulb and no mixing can occur.');
    });
}

function particlePosition(panel, p, t) {
  var progress;
  if (p.gas === 'H2') progress = Math.min(1, Math.pow(t / 58, 0.82));
  else progress = Math.min(1, Math.pow(t / 96, 0.92));
  progress = ease(progress);

  var opposite = (p.gas === 'H2' && p.end.side === 'right') || (p.gas === 'O2' && p.end.side === 'left') || p.end.side === 'tube';
  if (!opposite) {
    var wiggle = Math.sin((t * 0.11) + p.jitter * 8) * 5 * (t / 100);
    return {
      x: p.start.x + (p.end.x - p.start.x) * progress + wiggle,
      y: p.start.y + (p.end.y - p.start.y) * progress + Math.cos((t * 0.09) + p.jitter * 9) * 4 * (t / 100)
    };
  }

  var tubeY = panel.cy - 7 + p.jitter * 14;
  var leftMouth = { x: panel.lx + panel.r - 8, y: tubeY };
  var mid = { x: (panel.lx + panel.rx) / 2, y: tubeY };
  var rightMouth = { x: panel.rx - panel.r + 8, y: tubeY };
  var route = p.gas === 'H2'
    ? [p.start, leftMouth, mid, rightMouth, p.end]
    : [p.start, rightMouth, mid, leftMouth, p.end];
  return pathPosition(route, progress);
}

function renderMotion(panel, t) {
  panel.motionLayer.clear();
  if (t <= 0) return;
  var x = (panel.lx + panel.rx) / 2;
  var op = massMode ? 0.45 : 0.25;

  panel.motionLayer.line(x - 58, panel.cy - 26, x + 58, panel.cy - 26)
    .stroke({ color: blueFast, width: 3, opacity: op, linecap: 'round' });
  panel.motionLayer.polygon([[x + 58, panel.cy - 26], [x + 47, panel.cy - 32], [x + 49, panel.cy - 20]])
    .fill({ color: blueFast, opacity: op });

  panel.motionLayer.line(x + 42, panel.cy + 28, x - 31, panel.cy + 28)
    .stroke({ color: darkRedSlow, width: 3, opacity: op * 0.85, linecap: 'round' });
  panel.motionLayer.polygon([[x - 31, panel.cy + 28], [x - 20, panel.cy + 22], [x - 22, panel.cy + 34]])
    .fill({ color: darkRedSlow, opacity: op * 0.85 });
}

function renderPanel(idx, t) {
  var panel = panels[idx];
  panel.trailLayer.clear();
  panel.particleLayer.clear();

  var open = idx === 0 ? false : (idx === 2 ? true : t > 0);
  drawValve(panel, open);
  renderMotion(panel, t);

  for (var i = 0; i < panel.particles.length; i++) {
    var p = panel.particles[i];
    var pos = particlePosition(panel, p, t);

    if (massMode && t > 0 && idx === 1) {
      var oldT = Math.max(0, t - (p.gas === 'H2' ? 16 : 8));
      var old = particlePosition(panel, p, oldT);
      panel.trailLayer.line(old.x, old.y, pos.x, pos.y)
        .stroke({
          color: p.gas === 'H2' ? blueFast : darkRedSlow,
          width: p.gas === 'H2' ? 2.2 : 1.5,
          opacity: p.gas === 'H2' ? 0.34 : 0.22,
          linecap: 'round'
        });
    }

    var fill = p.gas === 'H2'
      ? (massMode ? '#e8fbff' : whiteGas)
      : (massMode ? darkRedSlow : redGas);
    var stroke = p.gas === 'H2' ? '#ffffff' : redGas;
    var r = p.gas === 'H2' && massMode ? 5.2 : 5.5;

    var dot = panel.particleLayer.circle(r * 2).center(pos.x, pos.y)
      .fill(fill)
      .stroke({ color: stroke, width: p.gas === 'H2' ? 1 : 0, opacity: 0.9 });

    dot.css('cursor', 'pointer')
      .on('mousemove', (function (gas) {
        return function (e) {
          showTooltip(gas === 'H2' ? 'H₂: lighter particles diffuse faster.' : 'O₂: heavier particles diffuse more slowly.', e);
        };
      })(p.gas))
      .on('mouseleave', function () { hideTooltip(); });
  }
}

function updateLegend() {
  legend.clear();
  var x = 1105, y = 18;
  legend.rect(176, 45).move(x - 18, y - 8).fill({ color: '#fff', opacity: 0.72 }).stroke('none');
  if (massMode) {
    legend.circle(12).center(x, y + 5).fill('#e8fbff').stroke({ color: blueFast, width: 1 });
    legend.line(x - 18, y + 5, x - 3, y + 5).stroke({ color: blueFast, width: 2, opacity: 0.45 });
    legend.text('H₂ lighter / faster').font({ family: 'sans-serif', size: 13 }).move(x + 12, y - 4).fill('#222');
    legend.circle(12).center(x, y + 25).fill(darkRedSlow);
    legend.line(x - 12, y + 25, x - 4, y + 25).stroke({ color: darkRedSlow, width: 2, opacity: 0.35 });
    legend.text('O₂ heavier / slower').font({ family: 'sans-serif', size: 13 }).move(x + 12, y + 16).fill('#222');
  } else {
    legend.circle(12).center(x, y + 5).fill('#fff').stroke({ color: '#ddd', width: 1 });
    legend.text('H₂ particles').font({ family: 'sans-serif', size: 13 }).move(x + 12, y - 4).fill('#222');
    legend.circle(12).center(x, y + 25).fill(redGas);
    legend.text('O₂ particles').font({ family: 'sans-serif', size: 13 }).move(x + 12, y + 16).fill('#222');
  }
}

function updateStatus() {
  var msg;
  if (currentTime <= 0) msg = 'Status: closed — separated gases';
  else if (currentTime < 40) msg = 'Status: just opened — H₂ spreads faster';
  else if (currentTime < 90) msg = 'Status: mixing — random motion, net diffusion';
  else msg = 'Status: near uniform mixture';
  statusText.text(msg);
}

function renderAll() {
  renderPanel(0, 0);
  renderPanel(1, currentTime);
  renderPanel(2, 100);
  updateLegend();
  updateStatus();
}
function update_elapsedTime(v) {
  currentTime = Math.max(0, Math.min(100, v));
  var out = document.getElementById('elapsedTimeVal');
  var slider = document.getElementById('elapsedTimeInput');
  if (out) out.value = String(Math.round(currentTime));
  if (slider) slider.value = String(Math.round(currentTime));
  renderAll();
}
function toggle_massCoding(on) {
  massMode = !!on;
  var cb = document.getElementById('massCodingInput');
  if (cb) cb.checked = massMode;
  renderAll();
}
function trigger_diffusionPlayback() {
  if (playing) {
    playing = false;
    if (rafId) cancelAnimationFrame(rafId);
    document.getElementById('diffusionPlaybackInput').textContent = '▶ Play diffusion';
    return;
  }
  playing = true;
  document.getElementById('diffusionPlaybackInput').textContent = 'Pause';
  var startClock = performance.now();
  var startT = currentTime >= 100 ? 0 : currentTime;
  function tick(now) {
    if (!playing) return;
    var t = startT + (now - startClock) / 45;
    if (t >= 100) {
      t = 100;
      playing = false;
      document.getElementById('diffusionPlaybackInput').textContent = '▶ Play diffusion';
    }
    update_elapsedTime(t);
    if (playing) rafId = requestAnimationFrame(tick);
  }
  rafId = requestAnimationFrame(tick);
}

var demoSteps = [
  {
    title: 'Separated gases',
    narration: 'With the stopcock closed, white H₂ particles are confined to the left bulb and red O₂ particles are confined to the right bulb. No diffusion occurs because the gases cannot pass through the closed valve.',
    state: { elapsedTime: 0, massCoding: 'Gas identity' }
  },
  {
    title: 'Stopcock opened',
    narration: 'Once the stopcock opens, particles begin crossing the connecting tube. More H₂ has moved into the O₂ bulb than O₂ has moved into the H₂ bulb because H₂ is lighter and diffuses faster.',
    state: { elapsedTime: 30, massCoding: 'Molecular mass emphasis' }
  },
  {
    title: 'Continuing random motion',
    narration: 'As time passes, both gases continue spreading through both bulbs. The net movement follows the concentration gradients even though each molecule moves randomly.',
    state: { elapsedTime: 65, massCoding: 'Molecular mass emphasis' }
  },
  {
    title: 'Uniform mixture',
    narration: 'Some time after opening the stopcock, both H₂ and O₂ are distributed approximately uniformly across both bulbs. Diffusion has reduced the concentration differences that drove the initial net movement.',
    state: { elapsedTime: 100, massCoding: 'Gas identity' }
  }
];

function applyStep(n) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, n));
  var step = demoSteps[currentStep];
  var narr = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narr) narr.textContent = step.narration;
  if (label) label.textContent = (currentStep + 1) + '/' + demoSteps.length + ' ' + step.title;

  var massOn = step.state.massCoding === 'Molecular mass emphasis';
  toggle_massCoding(massOn);
  update_elapsedTime(step.state.elapsedTime);
}
function prevStep() { applyStep(currentStep - 1); }
function nextStep() { applyStep(currentStep + 1); }

draw.rect(1300, 344).fill('#fff').back();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

