function rng(seed) {
  var s = seed >>> 0;
  return function () {
    s = (1664525 * s + 1013904223) >>> 0;
    return s / 4294967296;
  };
}
function ease(u) {
  u = Math.max(0, Math.min(1, u));
  return u * u * (3 - 2 * u);
}
function bulbPoint(cx, cy, r, rand) {
  var a = rand() * Math.PI * 2;
  var rr = Math.sqrt(rand()) * (r - 17);
  return { x: cx + Math.cos(a) * rr, y: cy + Math.sin(a) * rr };
}
function tubePoint(panel, rand) {
  var x1 = panel.lx + panel.r - 8;
  var x2 = panel.rx - panel.r + 8;
  return { x: x1 + rand() * (x2 - x1), y: panel.cy - 11 + rand() * 22 };
}
function finalPoint(panel, rand) {
  var q = rand();
  if (q < 0.465) {
    var p1 = bulbPoint(panel.lx, panel.cy, panel.r, rand);
    p1.zone = 'left';
    return p1;
  }
  if (q < 0.93) {
    var p2 = bulbPoint(panel.rx, panel.cy, panel.r, rand);
    p2.zone = 'right';
    return p2;
  }
  var p3 = tubePoint(panel, rand);
  p3.zone = 'tube';
  return p3;
}
function pathPosition(points, u) {
  if (u <= 0) return points[0];
  if (u >= 1) return points[points.length - 1];
  var lengths = [];
  var total = 0;
  for (var i = 0; i < points.length - 1; i++) {
    var dx = points[i + 1].x - points[i].x;
    var dy = points[i + 1].y - points[i].y;
    lengths[i] = Math.sqrt(dx * dx + dy * dy);
    total += lengths[i];
  }
  var target = u * total;
  var acc = 0;
  for (var j = 0; j < lengths.length; j++) {
    if (acc + lengths[j] >= target) {
      var f = (target - acc) / lengths[j];
      return {
        x: points[j].x + (points[j + 1].x - points[j].x) * f,
        y: points[j].y + (points[j + 1].y - points[j].y) * f
      };
    }
    acc += lengths[j];
  }
  return points[points.length - 1];
}
function makeParticles(panel, seed) {
  var local = rng(seed);
  var list = [];
  for (var i = 0; i < 31; i++) {
