function particlePosition(panel, particle, t) {
  if (t <= 0) return particle.start;

  var rate = particle.gas === 'H2' ? 54 : 92;
  var exponent = particle.gas === 'H2' ? 0.78 : 0.94;
  var progress = ease(Math.min(1, Math.pow(t / rate, exponent)));

  var tubeY = panel.cy - 8 + particle.jitter * 16;
  var leftMouth = { x: panel.lx + panel.r - 8, y: tubeY };
  var mid = { x: (panel.lx + panel.rx) / 2, y: tubeY };
  var rightMouth = { x: panel.rx - panel.r + 8, y: tubeY };

