        });
    }

    var fill = particle.gas === 'H2'
      ? (massMode ? '#e8fbff' : '#ffffff')
      : (massMode ? oSlow : redGas);
    var strokeColor = particle.gas === 'H2' ? '#ffffff' : redGas;
    var radius = particle.gas === 'H2' && massMode ? 5.0 : 5.4;

    var dot = panel.particleLayer.circle(radius * 2).center(pos.x, pos.y)
      .fill(fill)
      .stroke({ color: strokeColor, width: particle.gas === 'H2' ? 1 : 0, opacity: 0.95 });

    dot.css('cursor', 'pointer')
      .on('mousemove', (function (gas) {
        return function (e) {
          showTooltip(gas === 'H2' ? 'H₂: lighter particles diffuse faster.' : 'O₂: heavier particles diffuse more slowly.', e);
        };
      })(particle.gas))
      .on('mouseleave', function () { hideTooltip(); });
  }
}

for (var i = 0; i < panels.length; i++) drawApparatus(panels[i], i);

function renderAll() {
  renderPanel(0, 0);
  renderPanel(1, currentTime);
  renderPanel(2, 100);
}

function update_elapsedTime(v) {
  currentTime = Math.max(0, Math.min(100, v));
  var out = document.getElementById('elapsedTimeVal');
  var slider = document.getElementById('elapsedTimeInput');
  if (out) out.value = String(Math.round(currentTime));
  if (slider) slider.value = String(Math.round(currentTime));
  renderAll();
}

function toggle_massCoding(on) {
  massMode = !!on;
  var cb = document.getElementById('massCodingInput');
  if (cb) cb.checked = massMode;
  renderAll();
}

function trigger_diffusionPlayback() {
  if (playing) {
    playing = false;
    if (rafId) cancelAnimationFrame(rafId);
    var b0 = document.getElementById('diffusionPlaybackInput');
    if (b0) b0.textContent = '▶ Play diffusion';
    return;
  }
  playing = true;
  var b1 = document.getElementById('diffusionPlaybackInput');
  if (b1) b1.textContent = 'Pause';
  var startClock = performance.now();
  var startT = currentTime >= 100 ? 0 : currentTime;

  function tick(now) {
    if (!playing) return;
    var t = startT + (now - startClock) / 45;
    if (t >= 100) {
      t = 100;
      playing = false;
      var b2 = document.getElementById('diffusionPlaybackInput');
      if (b2) b2.textContent = '▶ Play diffusion';
    }
    update_elapsedTime(t);
    if (playing) rafId = requestAnimationFrame(tick);
  }
  rafId = requestAnimationFrame(tick);
}

