];

function applyStep(n) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, n));
  var step = demoSteps[currentStep];
  var narr = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narr) narr.textContent = step.narration;
  if (label) label.textContent = (currentStep + 1) + '/' + demoSteps.length + ' ' + step.title;

  toggle_massCoding(step.state.massCoding === 'Molecular mass emphasis');
  update_elapsedTime(step.state.elapsedTime);
}
function prevStep() { applyStep(currentStep - 1); }
function nextStep() { applyStep(currentStep + 1); }

